export function fans() {
  const ps = purchases();
  const agg = reqSummary().req?.fans ?? new Map<string, FanAgg>();
  // Fan summaries do not return ownership. Read receipts once and keep the
  // existing incremental request summary and unreadable-chat handling.
  const purchasesByChat = new Map<string, { count: number; stars: number }>();
  for (const p of ps) {
    const id = String(p.chatId), row = purchasesByChat.get(id) ?? { count: 0, stars: 0 };
    row.count++; row.stars += p.stars;
    purchasesByChat.set(id, row);
  }
  return chats(false).map((c) => {
    const mine = agg.get(c.id);
    const bought = purchasesByChat.get(c.id);
    return {
      chatId: c.id, name: c.who ?? null, username: c.who?.startsWith("@") ? c.who.slice(1) : null, business: !!c.bcid,
      firstSeen: mine?.first ?? null, lastSeen: mine?.last ?? c.updated, messages: c.messages, unreadable: c.unreadable,
      offered: mine?.offered ?? 0, // locked cards Telegram acknowledged
      offeredUnverified: mine?.unverified ?? 0, // older rows: selected, delivery never verified
      bought: bought?.count ?? 0, starsSpent: bought?.stars ?? 0,
    };
  });
}
